Method.Source:
public Map addTranslations()
{
    Map ret;

    ret = super();
    ret.insert('PageUnplannedPalletMoveTitle',"@MobileWMS:MoveLicensePlate");
    ret.insert('MainMenuUnplannedPalletMove',MobHelper::capitalLetterSentence("@MobileWMS:MoveLicensePlate"));
    ret.insert('PageCreatePalletTitle',"@WAX3180");
    ret.insert('MainMenuCreatePallet',MobHelper::capitalLetterSentence("@WAX3180"));
    return ret;
}

[TFMReferenceDataMethod(staticMethodStr(MobConstants, UnplannedCreatePallet))]
public TFMReferenceDataConfiguration CreatePalletHeader()
{
    TFMReferenceDataConfiguration refCon = new TFMReferenceDataConfiguration();  
    TFMRegistrationCollectorText  lpCol = TFMRegistrationCollector::collectorFromEDT(extendedTypeStr(WHSLicensePlateId));
    lpCol.parmOptional(false);
    refCon.addCollector(lpCol);
    return refCon;
}

[TFMReferenceDataMethod(staticMethodStr(MobConstants, UnplannedPalletMove))]
public TFMReferenceDataConfiguration UnplannedPalletMoveHeader()
{
    TFMReferenceDataConfiguration refCon = new TFMReferenceDataConfiguration();
    TFMRegistrationCollectorText  lpCol = TFMRegistrationCollector::collectorFromEDT(extendedTypeStr(WHSLicensePlateId));
    lpCol.parmOptional(false);
    refCon.addCollector(lpCol);
    refCon.addCollector(TFMGetReferenceData::defaultLocationCollector(20,'MoveTo'));

    return refCon;
}

[TFMPostMethod(tableStr(inventJournalTable))]
public void postCreatePallet()
{

    WHSLicensePlateId   licensePlate = request.getFieldValue(extendedTypeStr(WHSLicensePlateId));
    WHSLicensePlate     lp = WHSLicensePlate::createLicensePlate(licensePlate);
    resultStr = lp ? "@MobileWMS:MEL71" : "@MobileWMS:MEL65";
}

public void postUnplannedPalletMove()
{        
    wmsLocationid       WMSLocId= request.getFieldValue('MoveTo');
    WHSLicensePlateId   lp = request.getFieldValue(extendedTypeStr(WHSLicensePlateId));
    InventDim           inventDimIssue;
    InventSum           isum;

    select firstonly isum
        join inventDimIssue where inventDimIssue.inventDimId == isum.InventDimId
        &&   inventDimIssue.LicensePlateId == lp;

    MobPostHelper::MoveLicensePlate(lp,inventDimIssue.InventLocationId,wmslocid);

    resultStr = SysLabel::labelId2String2("@MobileWMS:MEL47");
}
